import{_ as e,o as t,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/ai-features/3-7-12-recommend-collaborator/report3_spec.md","filePath":"feature/ai-features/3-7-12-recommend-collaborator/report3_spec.md"}'),n={name:"feature/ai-features/3-7-12-recommend-collaborator/report3_spec.md"};function i(l,o,s,c,d,g){return t(),a("div",null,[...o[0]||(o[0]=[r('<p><strong>3.7.12 Recommend Collaborator</strong></p><p><strong>Function Trigger</strong></p><p>A Creator or Manager opens <code>/workspaces/:id/campaigns/:campaignId/recommend-collaborator</code> from within a Campaign to get AI-suggested media partners.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Creator, Manager.</li><li><strong>Purpose</strong>: Let a Creator/Manager ask AI for third-party media partner suggestions (newspapers, banner sites, TV channels) given industry/target audience/budget, then convert a chosen suggestion into a <code>ThirdPartyCollaborator</code> record (agency-level contact book) or link it to the current Campaign as a <code>CampaignCollaborator</code>.</li><li><strong>Interface</strong>: A Recommend Collaborator page showing AI-ranked suggestions with a &quot;save to contact book&quot; / &quot;link to campaign&quot; action.</li><li><strong>Data Processing</strong>: The system calls an AI model with <code>industry</code>/<code>targetAudience</code>/<code>budgetRange</code> and returns tiered recommendations; choosing one either creates a new <code>ThirdPartyCollaborator</code> row or attaches an existing one to the Campaign via <code>CampaignCollaborator</code>.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Recommend Collaborator View:</p><ul><li>Input panel: industry, target audience, budget range.</li><li>Results panel: ranked recommendation cards (name, type, tier, reason).</li><li>Per-card action: &quot;Add to Contacts&quot; (save to <code>ThirdPartyCollaborator</code>) or &quot;Link to Campaign&quot; (link as <code>CampaignCollaborator</code>).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: <code>industry</code>, <code>targetAudience</code>, <code>budgetRange</code> for the AI call; <code>collaboratorId</code> (if choosing from the existing contact book) or <code>newCollaborator{name, type, contactInfo}</code> for the link-to-campaign step.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: <code>ThirdPartyCollaborator</code> (agency-level contact book: agencyId, partnerName, partnerType, contactInfo, notes, createdBy) and <code>CampaignCollaborator</code> (mediaCampaignId, collaboratorId, cooperationStatus default <code>CONTACTED</code>, updatedBy).</li><li><strong>Output</strong>: AI recommendation list <code>{name, type, tier, reason}</code>; campaign-link response <code>{campaignCollaboratorId, collaboratorId, cooperationStatus}</code>.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li>AI only <em>suggests</em> partners — it never auto-contacts or signs anything.</li><li>A chosen suggestion may become a new <code>ThirdPartyCollaborator</code> (agency-level) or link an existing one to the Campaign (<code>CampaignCollaborator</code>).</li><li>Low-budget input still returns the lowest-tier suggestion with a warning rather than an empty list.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>No special validation errors beyond standard auth/permission checks.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ul><li><ol><li>A Creator/Manager opens the Recommend Collaborator page for a Campaign.</li></ol></li><li><ol start="2"><li>The client submits industry/targetAudience/budgetRange to the AI recommendation endpoint.</li></ol></li><li><ol start="3"><li>The system returns a tiered list of suggested partners.</li></ol></li><li><ol start="4"><li>The user picks a suggestion and either saves it as a new <code>ThirdPartyCollaborator</code> or links an existing one to the Campaign as a <code>CampaignCollaborator</code>.</li></ol></li></ul></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Budget too low for any strong match → the system still returns the lowest tier with a warning, not an empty list.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>A new <code>ThirdPartyCollaborator</code> or <code>CampaignCollaborator</code> row is created, available for follow-up tracking.</li></ul>',14)])])}const m=e(n,[["render",i]]);export{u as __pageData,m as default};
